import React from 'react';
import './optimizevideo.css'; // Import CSS for styling

const OptimizeVideo = () => {
  return (
    <div className="optimized-video-page">
      {/* Header Section */}
      <header className="page-header">
        <h1>Optimized Video Output</h1>
        <p>Your video has been optimized successfully. You can preview or download it below.</p>
      </header>

      {/* Video Output Section */}
      <div className="video-output">
        {/* Placeholder for video */}
        <video
          className="optimized-video"
          controls
          src="/path-to-your-optimized-video.mp4" // Replace with dynamic video source
          alt="Optimized Video Output"
        >
          Your browser does not support the video tag.
        </video>

        {/* Action Buttons */}
        <div className="action-buttons">
          <button className="preview-button" onClick={() => handlePreview()}>Preview</button>
          <button className="download-button" onClick={() => handleDownload()}>Download</button>
        </div>
      </div>
    </div>
  );

  // Function to handle preview action
  function handlePreview() {
    alert('Playing video preview...');
    // Additional functionality to enhance preview can be added here
  }

  // Function to handle download action
  function handleDownload() {
    const link = document.createElement('a');
    link.href = '/path-to-your-optimized-video.mp4'; // Replace with dynamic video path
    link.download = 'optimized-video.mp4';
    link.click();
  }
};

export default OptimizeVideo;
